    /// Returns the reconstructed exact catalog.
    pub const fn catalog(&self) -> &ProjectCatalog { &self.catalog }

    /// Admits the typed root under the exact catalog provider and schema.
    pub fn admit_root<H: CommitmentHasher>(
        &self,
        root: &crate::oracle::templates::agent_treasury_guard::generated::Treasury,
        limits: ValidationLimits,
    ) -> Result<SchemaAdmittedEnvelope, GeneratedProjectError> {
        self.validate_catalog::<H>()?;
        let value = root.to_value()?;
        Ok(SchemaAdmittedEnvelope::try_new::<H>(self.catalog.schema(), value, limits)?)
    }

    /// Admits a typed command and derives its exact commitment.
    pub fn admit_command<H: CommitmentHasher>(
        &self,
        command: &crate::oracle::templates::agent_treasury_guard::generated::TreasuryCommand,
        limits: ValidationLimits,
    ) -> Result<GeneratedCommandEnvelope, GeneratedProjectError> {
        self.validate_catalog::<H>()?;
        let value = command.to_value()?;
        let admitted = SchemaAdmittedTypeEnvelope::try_new::<H>(
            self.catalog.schema(), TypeId::new(COMMAND_TYPE_ID), value, limits,
        )?;
        let commitment = Self::input_commitment::<H>(GeneratedInputKind::Command, &admitted)?;
        Ok(GeneratedCommandEnvelope { admitted, commitment })
    }

    /// Admits a typed authenticated context and derives its exact commitment.
    pub fn admit_context<H: CommitmentHasher>(
        &self,
        context: &crate::oracle::templates::agent_treasury_guard::generated::GuardContext,
        limits: ValidationLimits,
    ) -> Result<GeneratedContextEnvelope, GeneratedProjectError> {
        self.validate_catalog::<H>()?;
        let value = context.to_value()?;
        let admitted = SchemaAdmittedTypeEnvelope::try_new::<H>(
            self.catalog.schema(), TypeId::new(CONTEXT_TYPE_ID), value, limits,
        )?;
        let commitment = Self::input_commitment::<H>(GeneratedInputKind::Context, &admitted)?;
        Ok(GeneratedContextEnvelope { admitted, commitment })
    }

    /// Starts a catalog-aware transition from schema-admitted inputs.
    pub fn begin_transition<'a, H: CommitmentHasher>(
        &'a self,
        pre_state: &'a SchemaAdmittedEnvelope,
        state_domain: Domain<'a>,
        command: &GeneratedCommandEnvelope,
        context: &GeneratedContextEnvelope,
        budget_used: BudgetUsed,
        limits: TransitionLimits,
    ) -> Result<GeneratedTransition<'a, H>, GeneratedProjectError> {
        let expected = crate::oracle::transition::ExpectedInvocationBindings::try_new(command.commitment(), context.commitment())?;
        self.begin_bound_transition::<H>(pre_state, state_domain, command, context, expected, budget_used, limits)
    }

    /// Starts a transition using the shell-owned complete invocation bindings.
    ///
    /// Pass `ReviewedTransitionInput::expected_bindings()` inside the reviewed program.
    /// The command must match its admitted value. The complete context binding includes
    /// authentication and replay data; only the authority can validate that relationship.
    /// This constructor creates a candidate builder and grants no commit authority.
    pub fn begin_bound_transition<'a, H: CommitmentHasher>(
        &'a self,
        pre_state: &'a SchemaAdmittedEnvelope,
        state_domain: Domain<'a>,
        command: &GeneratedCommandEnvelope,
        context: &GeneratedContextEnvelope,
        expected: crate::oracle::transition::ExpectedInvocationBindings,
        budget_used: BudgetUsed,
        limits: TransitionLimits,
    ) -> Result<GeneratedTransition<'a, H>, GeneratedProjectError> {
        self.validate_catalog::<H>()?;
        Self::validate_root_binding(pre_state.schema_hash(), pre_state.root_type())?;
        Self::validate_input::<H>(GeneratedInputKind::Command, command.admitted(), command.commitment())?;
        Self::validate_input::<H>(GeneratedInputKind::Context, context.admitted(), context.commitment())?;
        if expected.command_hash() != command.commitment() {
            return Err(GeneratedProjectError::InputCommitmentMismatch { kind: GeneratedInputKind::Command, expected: expected.command_hash(), actual: command.commitment() });
        }
        let inner = CataloguedTransitionBuilder::try_new(
            &self.catalog, pre_state.value().value(), state_domain, command.commitment(),
            expected.context_hash(), budget_used, limits,
        )?;
        Ok(GeneratedTransition { inner })
    }

    fn validate_root_binding(schema_hash: Hash32, root_type: TypeId) -> Result<(), GeneratedProjectError> {
        if schema_hash != SCHEMA_HASH {
            return Err(GeneratedProjectError::SchemaHashMismatch { expected: SCHEMA_HASH, actual: schema_hash });
        }
        if root_type != TypeId::new(STATE_TYPE_ID) {
            return Err(GeneratedProjectError::RootTypeMismatch { expected: STATE_TYPE_ID, actual: root_type.get() });
        }
        Ok(())
    }

    fn validate_input<H: CommitmentHasher>(
        kind: GeneratedInputKind,
        admitted: &SchemaAdmittedTypeEnvelope,
        expected_commitment: Hash32,
    ) -> Result<(), GeneratedProjectError> {
        let expected_type = match kind {
            GeneratedInputKind::Command => COMMAND_TYPE_ID,
            GeneratedInputKind::Context => CONTEXT_TYPE_ID,
        };
        if admitted.schema_hash() != SCHEMA_HASH {
            return Err(GeneratedProjectError::InputSchemaHashMismatch { kind, expected: SCHEMA_HASH, actual: admitted.schema_hash() });
        }
        if admitted.type_id() != TypeId::new(expected_type) {
            return Err(GeneratedProjectError::InputTypeMismatch { kind, expected: expected_type, actual: admitted.type_id().get() });
        }
        let actual = Self::input_commitment::<H>(kind, admitted)?;
        if actual != expected_commitment {
            return Err(GeneratedProjectError::InputCommitmentMismatch { kind, expected: expected_commitment, actual });
        }
        Ok(())
    }

    fn input_commitment<H: CommitmentHasher>(
        kind: GeneratedInputKind,
        admitted: &SchemaAdmittedTypeEnvelope,
    ) -> Result<Hash32, GeneratedProjectError> {
        let domain_name = match kind {
            GeneratedInputKind::Command => COMMAND_DOMAIN,
            GeneratedInputKind::Context => CONTEXT_DOMAIN,
        };
        let domain = Domain::new(domain_name, INPUT_COMMITMENT_FORMAT_VERSION)?;
        let bytes = admitted.canonical_bytes()?;
        let value = commitment::<H>(domain, &bytes)?;
        if value == Hash32::ZERO {
            return Err(GeneratedProjectError::ZeroInputCommitment(kind));
        }
        Ok(value)
    }

    fn validate_catalog<H: CommitmentHasher>(&self) -> Result<(), GeneratedProjectError> {
        if H::ALGORITHM_ID != HASH_ALGORITHM_ID {
            return Err(GeneratedProjectError::HashAlgorithmMismatch);
        }
        let actual_schema_hash = self.catalog.schema_hash();
        if actual_schema_hash != SCHEMA_HASH {
            return Err(GeneratedProjectError::SchemaHashMismatch { expected: SCHEMA_HASH, actual: actual_schema_hash });
        }
        let actual_profile_hash = self.catalog.profile_hash();
        if actual_profile_hash != PROFILE_HASH {
            return Err(GeneratedProjectError::ProfileHashMismatch { expected: PROFILE_HASH, actual: actual_profile_hash });
        }
        let actual_catalog_hash = self.catalog.commitment::<H>()?;
        if actual_catalog_hash != CATALOG_HASH {
            return Err(GeneratedProjectError::CatalogHashMismatch { expected: CATALOG_HASH, actual: actual_catalog_hash });
        }
        Ok(())
    }
